1	import "jsr:@supabase/functions-js/edge-runtime.d.ts";
2	import { createClient } from "jsr:@supabase/supabase-js@2";
3	
4	const corsHeaders = {
5	  "Access-Control-Allow-Origin": "*",
6	  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
7	};
8	
9	interface ParsedFilters {
10	  min_score?: number;
11	  max_score?: number;
12	  skills?: string[];
13	  location?: string;
14	  stages?: string[];
15	  min_experience_years?: number;
16	  education_level?: string;
17	  semantic_query?: string;
18	}
19	
20	Deno.serve(async (req) => {
21	  if (req.method === "OPTIONS") {
22	    return new Response("ok", { headers: corsHeaders });
23	  }
24	
25	  try {
26	    const supabase = createClient(
27	      Deno.env.get("SUPABASE_URL")!,
28	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
29	    );
30	
31	    const authHeader = req.headers.get("Authorization");
32	    if (!authHeader) {
33	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
34	        status: 401,
35	        headers: { ...corsHeaders, "Content-Type": "application/json" },
36	      });
37	    }
38	
39	    const token = authHeader.replace("Bearer ", "");
40	    const { data: { user }, error: authError } = await supabase.auth.getUser(token);
41	    if (authError || !user) {
42	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
43	        status: 401,
44	        headers: { ...corsHeaders, "Content-Type": "application/json" },
45	      });
46	    }
47	
48	    const { query, job_id } = await req.json() as { query: string; job_id?: string };
49	    if (!query?.trim()) {
50	      return new Response(JSON.stringify({ error: "query is required" }), {
51	        status: 400,
52	        headers: { ...corsHeaders, "Content-Type": "application/json" },
53	      });
54	    }
55	
56	    const openaiKey = Deno.env.get("OPENAI_API_KEY");
57	    if (!openaiKey) throw new Error("OPENAI_API_KEY not configured");
58	
59	    // Step 1: Parse NL query into structured filters via GPT-4o
60	    const parseResponse = await fetch("https://api.openai.com/v1/chat/completions", {
61	      method: "POST",
62	      headers: {
63	        "Authorization": `Bearer ${openaiKey}`,
64	        "Content-Type": "application/json",
65	      },
66	      body: JSON.stringify({
67	        model: "gpt-4o",
68	        messages: [
69	          {
70	            role: "system",
71	            content: `You are a resume search query parser. Parse natural language queries about candidates into structured JSON filters.
72	
73	Return ONLY valid JSON with this structure:
74	{
75	  "min_score": <number 0-100 or null>,
76	  "max_score": <number 0-100 or null>,
77	  "skills": [<array of skill strings or empty>],
78	  "location": <string or null>,
79	  "stages": [<array from: "applied","screened","interview","offer","hired","rejected" or empty>],
80	  "min_experience_years": <number or null>,
81	  "education_level": <"high_school"|"bachelor"|"master"|"phd" or null>,
82	  "semantic_query": <cleaned search terms for text search, or null>
83	}
84	
85	Examples:
86	"Show me candidates with React over 80%" → {"min_score":80,"skills":["React"],"semantic_query":"React"}
87	"Senior engineers in New York" → {"location":"New York","min_experience_years":5,"semantic_query":"senior engineer"}
88	"Python developers in interview stage" → {"skills":["Python"],"stages":["interview"],"semantic_query":"Python developer"}`,
89	          },
90	          { role: "user", content: query },
91	        ],
92	        temperature: 0,
93	        max_tokens: 400,
94	        response_format: { type: "json_object" },
95	      }),
96	    });
97	
98	    if (!parseResponse.ok) throw new Error("Failed to parse query");
99	
100	    const parseCompletion = await parseResponse.json();
101	    const filters: ParsedFilters = JSON.parse(
102	      parseCompletion.choices?.[0]?.message?.content ?? "{}"
103	    );
104	
105	    // Step 2: Build DB query using parsed filters
106	    let dbQuery = supabase
107	      .from("resumes")
108	      .select(`
109	        id,
110	        filename,
111	        candidate_name,
112	        candidate_location,
113	        candidate_email,
114	        job_id,
115	        status,
116	        parsed_json,
117	        results!inner (
118	          id,
119	          overall_score,
120	          skill_score,
121	          experience_score,
122	          education_score,
123	          missing_skills,
124	          strengths_json,
125	          gaps_json,
126	          authenticity_json
127	        ),
128	        jobs!inner (
129	          id,
130	          title,
131	          user_id
132	        )
133	      `)
134	      .eq("jobs.user_id", user.id)
135	      .eq("status", "done");
136	
137	    if (job_id) {
138	      dbQuery = dbQuery.eq("job_id", job_id);
139	    }
140	
141	    if (filters.min_score != null) {
142	      dbQuery = dbQuery.gte("results.overall_score", filters.min_score);
143	    }
144	    if (filters.max_score != null) {
145	      dbQuery = dbQuery.lte("results.overall_score", filters.max_score);
146	    }
147	    if (filters.location) {
148	      dbQuery = dbQuery.ilike("candidate_location", `%${filters.location}%`);
149	    }
150	
151	    const { data: candidates, error: queryErr } = await dbQuery
152	      .order("results.overall_score", { ascending: false })
153	      .limit(50);
154	
155	    if (queryErr) throw queryErr;
156	
157	    // Step 3: Client-side filter for skills (if any)
158	    let filtered = candidates ?? [];
159	
160	    if (filters.skills && filters.skills.length > 0) {
161	      const skillsLower = filters.skills.map((s) => s.toLowerCase());
162	      filtered = filtered.filter((c: any) => {
163	        const parsed = typeof c.parsed_json === "string"
164	          ? JSON.parse(c.parsed_json)
165	          : c.parsed_json ?? {};
166	        const candidateSkills: string[] = (parsed.skills ?? []).map((s: string) => s.toLowerCase());
167	        return skillsLower.some((skill) =>
168	          candidateSkills.some((cs) => cs.includes(skill))
169	        );
170	      });
171	    }
172	
173	    if (filters.semantic_query) {
174	      const q = filters.semantic_query.toLowerCase();
175	      filtered = filtered.filter((c: any) => {
176	        const name = (c.candidate_name ?? c.filename ?? "").toLowerCase();
177	        const location = (c.candidate_location ?? "").toLowerCase();
178	        const parsed = typeof c.parsed_json === "string"
179	          ? JSON.parse(c.parsed_json)
180	          : c.parsed_json ?? {};
181	        const skills = (parsed.skills ?? []).join(" ").toLowerCase();
182	        const summary = (parsed.summary ?? "").toLowerCase();
183	        return (
184	          name.includes(q) ||
185	          location.includes(q) ||
186	          skills.includes(q) ||
187	          summary.includes(q)
188	        );
189	      });
190	    }
191	
192	    const results = filtered.map((c: any) => ({
193	      resume_id: c.id,
194	      filename: c.filename,
195	      candidate_name: c.candidate_name,
196	      candidate_location: c.candidate_location,
197	      candidate_email: c.candidate_email,
198	      job_id: c.job_id,
199	      job_title: c.jobs?.title ?? null,
200	      overall_score: c.results?.[0]?.overall_score ?? 0,
201	      skill_score: c.results?.[0]?.skill_score ?? 0,
202	      experience_score: c.results?.[0]?.experience_score ?? 0,
203	      education_score: c.results?.[0]?.education_score ?? 0,
204	      authenticity_json: c.results?.[0]?.authenticity_json ?? null,
205	    }));
206	
207	    return new Response(
208	      JSON.stringify({ results, filters, total: results.length }),
209	      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
210	    );
211	  } catch (error: unknown) {
212	    const message = error instanceof Error ? error.message : "Unknown error";
213	    console.error("ai-search error:", message);
214	    return new Response(JSON.stringify({ error: message }), {
215	      status: 500,
216	      headers: { ...corsHeaders, "Content-Type": "application/json" },
217	    });
218	  }
219	});
