1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
3	
4	const ALLOWED_ORIGINS = [
5	  Deno.env.get("APP_URL") || "https://rankora.co",
6	  "https://www.rankora.co",
7	  "http://localhost:8080",
8	  "http://localhost:5173",
9	];
10	
11	function getCorsOrigin(req: Request): string {
12	  const origin = req.headers.get("origin") || "";
13	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
14	}
15	
16	const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
17	const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
18	const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
19	
20	serve(async (req) => {
21	  const corsHeaders = {
22	    "Access-Control-Allow-Origin": getCorsOrigin(req),
23	    "Access-Control-Allow-Headers":
24	      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
25	  };
26	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
27	
28	  try {
29	    // Auth check
30	    const authHeader = req.headers.get("Authorization");
31	    if (!authHeader) throw new Error("No auth header");
32	
33	    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
34	    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
35	      global: { headers: { Authorization: authHeader } },
36	    });
37	    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
38	    if (userError || !user) throw new Error("Unauthorized");
39	
40	    // No credit deduction — generation is free
41	
42	    const body = await req.json();
43	    const {
44	      job_title,
45	      company_name,
46	      key_responsibilities,
47	      requirements,
48	      nice_to_haves,
49	      employment_type,
50	      location,
51	      salary_range,
52	      tone,
53	    } = body;
54	
55	    if (!job_title?.trim()) throw new Error("Missing job_title");
56	    if (!key_responsibilities?.trim()) throw new Error("Missing key_responsibilities");
57	    if (!requirements?.trim()) throw new Error("Missing requirements");
58	
59	    // Input length limits to prevent abuse
60	    if (job_title.length > 200) throw new Error("job_title too long (max 200 chars)");
61	    if (key_responsibilities.length > 5000) throw new Error("key_responsibilities too long (max 5000 chars)");
62	    if (requirements.length > 5000) throw new Error("requirements too long (max 5000 chars)");
63	    if (nice_to_haves && nice_to_haves.length > 5000) throw new Error("nice_to_haves too long (max 5000 chars)");
64	    if (company_name && company_name.length > 200) throw new Error("company_name too long (max 200 chars)");
65	    if (location && location.length > 200) throw new Error("location too long (max 200 chars)");
66	    if (salary_range && salary_range.length > 200) throw new Error("salary_range too long (max 200 chars)");
67	
68	    const toneInstruction =
69	      tone === "Casual"
70	        ? "Use a friendly, approachable tone. Avoid stiff corporate language."
71	        : tone === "Startup"
72	        ? "Use an energetic, mission-driven startup tone. Emphasize impact and growth."
73	        : "Use a professional, formal tone suitable for established companies.";
74	
75	    const systemPrompt = `You are an expert HR copywriter and technical recruiter specializing in ATS-optimized job descriptions. Your task is to generate a complete, compelling job description from the provided inputs.
76	
77	GENERATION GUIDELINES:
78	- Structure the JD with clear sections: About the Role, Key Responsibilities, Requirements, Nice-to-Have, What We Offer
79	- Use inclusive, bias-free language
80	- Ensure ATS-friendliness: standard section headers, bullet points, spell out acronyms on first use
81	- ${toneInstruction}
82	- Keep the About the Role section to 2-4 sentences that capture the essence and impact of the position
83	- Key Responsibilities: 5-8 clear bullet points using action verbs
84	- Requirements: 5-8 must-have qualifications, specific and measurable
85	- Nice-to-Have: 3-5 bonus qualifications
86	- What We Offer: 4-6 benefits/perks bullets (use generic competitive offerings if none provided)
87	- If company_name, location, employment_type, or salary_range are provided, incorporate them naturally
88	
89	Return ONLY valid JSON with this exact structure:
90	{
91	  "job_description": "the complete formatted job description as a single string with \\n for line breaks",
92	  "sections": {
93	    "about": "...",
94	    "responsibilities": "...",
95	    "requirements": "...",
96	    "nice_to_haves": "...",
97	    "benefits": "..."
98	  }
99	}`;
100	
101	    const userMessage = [
102	      `Job Title: ${job_title.trim()}`,
103	      company_name ? `Company: ${company_name.trim()}` : null,
104	      employment_type ? `Employment Type: ${employment_type}` : null,
105	      location ? `Location: ${location.trim()}` : null,
106	      salary_range ? `Salary Range: ${salary_range.trim()}` : null,
107	      `\nKey Responsibilities:\n${key_responsibilities.trim()}`,
108	      `\nRequirements:\n${requirements.trim()}`,
109	      nice_to_haves ? `\nNice-to-Have:\n${nice_to_haves.trim()}` : null,
110	    ]
111	      .filter(Boolean)
112	      .join("\n");
113	
114	    const response = await fetch("https://api.openai.com/v1/chat/completions", {
115	      method: "POST",
116	      headers: {
117	        Authorization: `Bearer ${OPENAI_API_KEY}`,
118	        "Content-Type": "application/json",
119	      },
120	      body: JSON.stringify({
121	        model: "gpt-4o",
122	        messages: [
123	          { role: "system", content: systemPrompt },
124	          { role: "user", content: userMessage },
125	        ],
126	        response_format: { type: "json_object" },
127	        temperature: 0.4,
128	      }),
129	    });
130	
131	    if (!response.ok) {
132	      const errBody = await response.text();
133	      throw new Error(`OpenAI API error ${response.status}: ${errBody.slice(0, 200)}`);
134	    }
135	
136	    const aiData = await response.json();
137	    const content = aiData.choices?.[0]?.message?.content;
138	    if (!content) throw new Error("OpenAI returned empty response");
139	
140	    const parsed = JSON.parse(content);
141	
142	    if (!parsed.job_description || !parsed.sections) {
143	      throw new Error("Unexpected response structure from OpenAI");
144	    }
145	
146	    return new Response(
147	      JSON.stringify({
148	        success: true,
149	        job_description: parsed.job_description,
150	        sections: parsed.sections,
151	      }),
152	      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
153	    );
154	  } catch (err) {
155	    console.error("generate-jd error:", err);
156	    return new Response(
157	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
158	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
159	    );
160	  }
161	});
