63	// ─── Job Metadata (for career page) ─────────────────────────────────────────
64	
65	function JobMetadataSection({ jobId }: { jobId: string }) {
66	  const [open, setOpen] = useState(false);
67	  const [location, setLocation] = useState("");
68	  const [department, setDepartment] = useState("");
69	  const [employmentType, setEmploymentType] = useState("Full-time");
70	  const [salaryRange, setSalaryRange] = useState("");
71	  const [expiresAt, setExpiresAt] = useState("");
72	  const [isFeatured, setIsFeatured] = useState(false);
73	  const [saving, setSaving] = useState(false);
74	  // loaded tracks whether DB data has been fetched — blocks form render until then
75	  // to prevent user input being silently overwritten by the async load.
76	  const [loaded, setLoaded] = useState(false);
77	
78	  useEffect(() => {
79	    // Reset loaded state when job changes so we don't show stale data
80	    setLoaded(false);
81	    setLocation("");
82	    setDepartment("");
83	    setEmploymentType("Full-time");
84	    setSalaryRange("");
85	    setExpiresAt("");
86	    setIsFeatured(false);
87	
88	    let cancelled = false;
89	    (async () => {
90	      const { data } = await (supabase as any)
91	        .from("jobs")
92	        .select("location, department, employment_type, salary_range, expires_at, is_featured")
