import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

const MATCH_THRESHOLD = 0.65;
const MATCH_COUNT = 20;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── Auth ──────────────────────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const token = authHeader.replace("Bearer ", "");
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(token);

    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Validate input ────────────────────────────────────────────────────────
    const body = await req.json() as { job_id?: string };
    const { job_id } = body;

    if (!job_id || typeof job_id !== "string") {
      return new Response(JSON.stringify({ error: "job_id is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Verify job ownership + fetch jd_embedding ─────────────────────────────
    const { data: job, error: jobError } = await supabase
      .from("jobs")
      .select("id, user_id, title, jd_embedding")
      .eq("id", job_id)
      .single();

    if (jobError || !job) {
      return new Response(JSON.stringify({ error: "Job not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (job.user_id !== user.id) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!job.jd_embedding) {
      // JD embedding not yet computed — return empty (feature not ready for this job)
      return new Response(
        JSON.stringify({ rediscovered: [], message: "JD embedding not available yet" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // ── pgvector similarity search via RPC ────────────────────────────────────
    const { data: similarResumes, error: rpcError } = await supabase.rpc(
      "find_similar_resumes",
      {
        target_embedding: job.jd_embedding,
        owner_id: user.id,
        exclude_job_id: job_id,
        match_threshold: MATCH_THRESHOLD,
        match_count: MATCH_COUNT,
      },
    );

    if (rpcError) {
      console.error("find_similar_resumes RPC error:", rpcError);
      throw new Error("Similarity search failed");
    }

    if (!similarResumes || similarResumes.length === 0) {
      return new Response(
        JSON.stringify({ rediscovered: [] }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // ── Enrich with original job titles ──────────────────────────────────────
    const jobIds = [...new Set((similarResumes as Array<{ job_id: string }>).map((r) => r.job_id))];

    const { data: originalJobs, error: jobsError } = await supabase
      .from("jobs")
      .select("id, title")
      .in("id", jobIds)
      .eq("user_id", user.id); // double-check ownership

    if (jobsError) {
      console.error("Failed to fetch original job titles:", jobsError);
    }

    const jobTitleMap = new Map<string, string>(
      (originalJobs ?? []).map((j: { id: string; title: string }) => [j.id, j.title]),
    );

    // ── Build response ────────────────────────────────────────────────────────
    type SimilarResume = {
      resume_id: string;
      job_id: string;
      candidate_name: string | null;
      filename: string;
      similarity: number;
      overall_score: number;
    };

    const rediscovered = (similarResumes as SimilarResume[]).map((r) => ({
      resume_id: r.resume_id,
      candidate_name: r.candidate_name ?? r.filename.replace(/\.\w+$/, ""),
      filename: r.filename,
      similarity: Math.round(r.similarity * 100), // as integer percent
      original_job_id: r.job_id,
      original_job_title: jobTitleMap.get(r.job_id) ?? "Unknown job",
      overall_score_on_original_job: r.overall_score ? Math.round(Number(r.overall_score)) : null,
    }));

    return new Response(
      JSON.stringify({ rediscovered }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("rediscover-candidates error:", message);
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── Auth ──────────────────────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const token = authHeader.replace("Bearer ", "");
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(token);

    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Validate input ────────────────────────────────────────────────────────
    const body = await req.json() as {
      job_id?: string;
      source_resume_ids?: string[];
    };

    const { job_id, source_resume_ids } = body;

    if (!job_id || typeof job_id !== "string") {
      return new Response(JSON.stringify({ error: "job_id is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (
      !source_resume_ids ||
      !Array.isArray(source_resume_ids) ||
      source_resume_ids.length === 0
    ) {
      return new Response(
        JSON.stringify({ error: "source_resume_ids must be a non-empty array" }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        },
      );
    }

    if (source_resume_ids.length > 20) {
      return new Response(
        JSON.stringify({ error: "Cannot import more than 20 resumes at once" }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        },
      );
    }

    // ── Verify target job ownership ───────────────────────────────────────────
    const { data: targetJob, error: targetJobError } = await supabase
      .from("jobs")
      .select("id, user_id, status")
      .eq("id", job_id)
      .single();

    if (targetJobError || !targetJob) {
      return new Response(JSON.stringify({ error: "Target job not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (targetJob.user_id !== user.id) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Fetch source resumes (verify ownership via jobs join) ─────────────────
    const { data: sourceResumes, error: sourceError } = await supabase
      .from("resumes")
      .select(
        "id, job_id, filename, file_path, candidate_name, parsed_json, parsed_text, embedding, status",
      )
      .in("id", source_resume_ids)
      .eq("status", "done");

    if (sourceError) {
      console.error("Failed to fetch source resumes:", sourceError);
      throw new Error("Failed to fetch source resumes");
    }

    if (!sourceResumes || sourceResumes.length === 0) {
      return new Response(
        JSON.stringify({ error: "No valid source resumes found" }),
        {
          status: 404,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        },
      );
    }

    // Verify all source resumes belong to the same user (via their original job)
    const sourceJobIds = [...new Set(sourceResumes.map((r: { job_id: string }) => r.job_id))];
    const { data: sourceJobs, error: sourceJobsError } = await supabase
      .from("jobs")
      .select("id, user_id")
      .in("id", sourceJobIds);

    if (sourceJobsError) throw new Error("Failed to verify source job ownership");

    const unauthorizedJobs = (sourceJobs ?? []).filter(
      (j: { id: string; user_id: string }) => j.user_id !== user.id,
    );
    if (unauthorizedJobs.length > 0) {
      return new Response(JSON.stringify({ error: "Forbidden: some resumes do not belong to you" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Check for already-imported resumes (avoid duplicates) ─────────────────
    const { data: existingResumes } = await supabase
      .from("resumes")
      .select("file_path")
      .eq("job_id", job_id);

    const existingFilePaths = new Set(
      (existingResumes ?? []).map((r: { file_path: string }) => r.file_path),
    );

    type SourceResume = {
      id: string;
      job_id: string;
      filename: string;
      file_path: string;
      candidate_name: string | null;
      parsed_json: unknown;
      parsed_text: string | null;
      embedding: unknown;
      status: string;
    };

    const toImport = (sourceResumes as SourceResume[]).filter(
      (r) => !existingFilePaths.has(r.file_path),
    );

    if (toImport.length === 0) {
      return new Response(
        JSON.stringify({
          imported: [],
          skipped: source_resume_ids.length,
          message: "All selected candidates are already in this job",
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // ── Insert cloned resume rows ─────────────────────────────────────────────
    const newRows = toImport.map((r) => ({
      job_id: job_id,
      filename: r.filename,
      file_path: r.file_path,
      candidate_name: r.candidate_name,
      parsed_json: r.parsed_json,
      parsed_text: r.parsed_text,
      embedding: r.embedding,
      status: "done", // already parsed — ready for ranking
    }));

    const { data: inserted, error: insertError } = await supabase
      .from("resumes")
      .insert(newRows)
      .select("id, filename, candidate_name");

    if (insertError) {
      console.error("Failed to insert cloned resumes:", insertError);
      throw new Error("Failed to import resumes");
    }

    const importedIds = (inserted ?? []).map((r: { id: string }) => r.id);
    const skippedCount = sourceResumes.length - toImport.length;

    // ── Trigger ranking for the imported resumes ──────────────────────────────
    // Fire-and-forget: rank the new resume rows against the target job.
    // We call rank-resumes but only for the newly imported resume IDs.
    // This is async — we don't wait for it to complete.
    if (importedIds.length > 0) {
      const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
      const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

      // Trigger via internal HTTP (fire-and-forget)
      fetch(`${supabaseUrl}/functions/v1/rank-resumes`, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${serviceKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          job_id: job_id,
          resume_ids: importedIds,
        }),
      }).catch((err) => {
        console.error("Failed to trigger ranking for imported resumes:", err);
      });
    }

    return new Response(
      JSON.stringify({
        imported: inserted ?? [],
        skipped: skippedCount,
        message: `${importedIds.length} candidate${importedIds.length !== 1 ? "s" : ""} imported. Ranking in progress.`,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("import-rediscovered error:", message);
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface RediscoveredCandidate {
  resume_id: string;
  candidate_name: string;
  filename: string;
  /** Similarity to current job's JD, 0–100 */
  similarity: number;
  original_job_id: string;
  original_job_title: string;
  /** Overall score from original job ranking, or null if not yet ranked */
  overall_score_on_original_job: number | null;
}

interface RediscoverResponse {
  rediscovered: RediscoveredCandidate[];
  message?: string;
}

interface ImportResponse {
  imported: Array<{ id: string; filename: string; candidate_name: string | null }>;
  skipped: number;
  message: string;
}

// ─── Hook: useRediscoveredCandidates ────────────────────────────────────────

/**
 * Fetches past candidates whose embeddings are similar to the current job's JD embedding.
 * Only runs when:
 *   - user is authenticated
 *   - a jobId is provided
 * Returns empty array (not loading) when disabled.
 */
export function useRediscoveredCandidates(jobId: string | null) {
  return useQuery<RediscoveredCandidate[]>({
    queryKey: ["rediscovery", jobId],
    queryFn: async (): Promise<RediscoveredCandidate[]> => {
      if (!jobId) return [];

      const { data, error } = await supabase.functions.invoke<RediscoverResponse>(
        "rediscover-candidates",
        { body: { job_id: jobId } },
      );

      if (error) throw error;
      return data?.rediscovered ?? [];
    },
    enabled: !!jobId,
    staleTime: 5 * 60 * 1000, // 5 minutes — similarity results don't change often
    retry: 1,
  });
}

// ─── Hook: useImportRediscovered ────────────────────────────────────────────

/**
 * Imports selected past-candidate resumes into the current job and triggers ranking.
 * Invalidates the job's resumes and results query keys after success.
 */
export function useImportRediscovered(jobId: string) {
  const queryClient = useQueryClient();

  return useMutation<ImportResponse, Error, string[]>({
    mutationFn: async (sourceResumeIds: string[]): Promise<ImportResponse> => {
      const { data, error } = await supabase.functions.invoke<ImportResponse>(
        "import-rediscovered",
        { body: { job_id: jobId, source_resume_ids: sourceResumeIds } },
      );

      if (error) throw error;
      if (!data) throw new Error("No response from import function");
      return data;
    },

    onSuccess: (response) => {
      toast.success(response.message ?? "Candidates imported");

      // Invalidate queries so the job detail view refetches resumes + results
      queryClient.invalidateQueries({ queryKey: ["resumes", jobId] });
      queryClient.invalidateQueries({ queryKey: ["results", jobId] });
      queryClient.invalidateQueries({ queryKey: ["existing-resumes", jobId] });
    },

    onError: (error) => {
      toast.error(`Import failed: ${error.message}`);
    },
  });
}

import { X, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useRediscoveredCandidates } from "@/hooks/useRediscovery";

interface RediscoveryBannerProps {
  jobId: string;
  onViewCandidates: () => void;
  onDismiss: () => void;
}

/**
 * Dismissible banner shown at the top of the results section when past candidates
 * match the current job's JD via vector similarity.
 * Auto-hides when there are no matches or data is still loading.
 */
const RediscoveryBanner = ({ jobId, onViewCandidates, onDismiss }: RediscoveryBannerProps) => {
  const { data: candidates, isLoading } = useRediscoveredCandidates(jobId);

  // Don't render anything until we know there are matches
  if (isLoading || !candidates || candidates.length === 0) return null;

  const count = candidates.length;

  return (
    <div
      className="flex items-center justify-between gap-3 rounded-lg border border-primary/30 bg-primary/5 px-4 py-3 animate-fade-in"
      role="status"
      aria-live="polite"
    >
      <div className="flex items-center gap-3 min-w-0">
        <Sparkles className="h-4 w-4 shrink-0 text-primary" aria-hidden="true" />
        <p className="text-sm font-medium text-foreground leading-snug">
          <span className="text-primary">{count}</span>{" "}
          past candidate{count !== 1 ? "s" : ""} match this role
        </p>
        <p className="text-sm text-muted-foreground hidden sm:block">
          — Rediscovered from your talent history
        </p>
      </div>

      <div className="flex items-center gap-2 shrink-0">
        <Button
          size="sm"
          variant="default"
          className="h-7 text-xs gap-1.5"
          onClick={onViewCandidates}
        >
          View {count > 1 ? `all ${count}` : "candidate"}
        </Button>
        <button
          onClick={onDismiss}
          className="rounded p-1 text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
          aria-label="Dismiss rediscovery banner"
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>
    </div>
  );
};

export default RediscoveryBanner;

