import { useState } from "react";
import { Sparkles, Loader2, CheckCircle2, Briefcase, TrendingUp } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { useRediscoveredCandidates, useImportRediscovered } from "@/hooks/useRediscovery";
import type { RediscoveredCandidate } from "@/hooks/useRediscovery";

// ─── Similarity badge colour ──────────────────────────────────────────────────

function similarityVariant(pct: number): "default" | "secondary" | "outline" {
  if (pct >= 80) return "default";
  if (pct >= 70) return "secondary";
  return "outline";
}

// ─── Candidate row ────────────────────────────────────────────────────────────

interface CandidateItemProps {
  candidate: RediscoveredCandidate;
  selected: boolean;
  imported: boolean;
  onToggle: (id: string) => void;
}

function CandidateItem({ candidate, selected, imported, onToggle }: CandidateItemProps) {
  return (
    <div
      className={`flex items-center gap-3 rounded-lg border p-3 cursor-pointer transition-colors ${
        imported
          ? "border-border bg-muted/30 opacity-60 cursor-not-allowed"
          : selected
          ? "border-primary/60 bg-primary/5"
          : "border-border hover:border-primary/30 hover:bg-muted/30"
      }`}
      onClick={() => !imported && onToggle(candidate.resume_id)}
      role="checkbox"
      aria-checked={selected}
      aria-disabled={imported}
      tabIndex={imported ? -1 : 0}
      onKeyDown={(e) => {
        if (!imported && (e.key === " " || e.key === "Enter")) {
          e.preventDefault();
          onToggle(candidate.resume_id);
        }
      }}
    >
      {/* Checkbox indicator */}
      <div
        className={`h-4 w-4 shrink-0 rounded border flex items-center justify-center transition-colors ${
          imported
            ? "border-muted bg-muted"
            : selected
            ? "border-primary bg-primary"
            : "border-muted-foreground/40"
        }`}
        aria-hidden="true"
      >
        {(selected || imported) && (
          <CheckCircle2 className={`h-3 w-3 ${imported ? "text-muted-foreground" : "text-primary-foreground"}`} />
        )}
      </div>

      {/* Info */}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">
          {candidate.candidate_name}
          {imported && (
            <span className="ml-2 text-xs text-muted-foreground font-normal">
              (already imported)
            </span>
          )}
        </p>
        <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
          <Briefcase className="h-3 w-3 text-muted-foreground shrink-0" />
          <span className="text-xs text-muted-foreground truncate max-w-[180px]">
            {candidate.original_job_title}
          </span>
          {candidate.overall_score_on_original_job !== null && (
            <>
              <span className="text-muted-foreground text-xs">·</span>
              <TrendingUp className="h-3 w-3 text-muted-foreground shrink-0" />
              <span className="text-xs text-muted-foreground">
                {candidate.overall_score_on_original_job}% on original
              </span>
            </>
          )}
        </div>
      </div>

      {/* Similarity badge */}
      <Badge
        variant={similarityVariant(candidate.similarity)}
        className="shrink-0 text-xs font-semibold tabular-nums"
        aria-label={`${candidate.similarity}% similarity to current job`}
      >
        {candidate.similarity}% match
      </Badge>
    </div>
  );
}

// ─── Skeleton loading state ───────────────────────────────────────────────────

function RediscoverySkeletonList() {
  return (
    <div className="space-y-2">
      {[1, 2, 3].map((i) => (
        <div key={i} className="flex items-center gap-3 rounded-lg border border-border p-3">
          <Skeleton className="h-4 w-4 rounded shrink-0" />
          <div className="flex-1 space-y-1.5">
            <Skeleton className="h-4 w-40" />
            <Skeleton className="h-3 w-56" />
          </div>
          <Skeleton className="h-5 w-20 rounded-full" />
        </div>
      ))}
    </div>
  );
}

// ─── Main dialog ──────────────────────────────────────────────────────────────

interface RediscoveryDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  jobId: string;
  /** IDs of resumes already in this job (to show as already-imported) */
  existingResumePaths?: Set<string>;
}

const RediscoveryDialog = ({
  open,
  onOpenChange,
  jobId,
  existingResumePaths,
}: RediscoveryDialogProps) => {
  const { data: candidates, isLoading, error } = useRediscoveredCandidates(open ? jobId : null);
  const { mutate: importCandidates, isPending: isImporting } = useImportRediscovered(jobId);

  const [selected, setSelected] = useState<Set<string>>(new Set());

  const toggleCandidate = (resumeId: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(resumeId)) next.delete(resumeId);
      else next.add(resumeId);
      return next;
    });
  };

  const handleImport = () => {
    if (selected.size === 0) return;
    importCandidates([...selected], {
      onSuccess: () => {
        setSelected(new Set());
        onOpenChange(false);
      },
    });
  };

  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen) setSelected(new Set());
    onOpenChange(nextOpen);
  };

  const count = candidates?.length ?? 0;

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-[560px] max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-4 w-4 text-primary" />
            Rediscovered Candidates
          </DialogTitle>
          <DialogDescription>
            {isLoading
              ? "Searching your talent history…"
              : count > 0
              ? `${count} past candidate${count !== 1 ? "s" : ""} match this role based on JD similarity. Select any to import and re-rank.`
              : "No matching candidates found in your talent history."}
          </DialogDescription>
        </DialogHeader>

        {/* Candidate list */}
        <div className="flex-1 overflow-y-auto space-y-2 py-1 min-h-0">
          {isLoading && <RediscoverySkeletonList />}

          {!isLoading && error && (
            <div className="text-sm text-destructive text-center py-6">
              Failed to load candidates. Please try again.
            </div>
          )}

          {!isLoading && !error && count === 0 && (
            <div className="text-sm text-muted-foreground text-center py-8">
              No past candidates match this job description yet.
              <br />
              As you rank more candidates, they will appear here automatically.
            </div>
          )}

          {!isLoading && candidates && candidates.map((candidate) => {
            const alreadyImported = Boolean(
              existingResumePaths?.has(candidate.resume_id),
            );
            return (
              <CandidateItem
                key={candidate.resume_id}
                candidate={candidate}
                selected={selected.has(candidate.resume_id)}
                imported={alreadyImported}
                onToggle={toggleCandidate}
              />
            );
          })}
        </div>

        {/* Footer */}
        {count > 0 && (
          <div className="flex items-center justify-between gap-3 pt-3 border-t border-border">
            <p className="text-xs text-muted-foreground">
              {selected.size > 0
                ? `${selected.size} candidate${selected.size !== 1 ? "s" : ""} selected`
                : "Select candidates to import"}
            </p>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => handleOpenChange(false)}
                disabled={isImporting}
              >
                Cancel
              </Button>
              <Button
                size="sm"
                onClick={handleImport}
                disabled={selected.size === 0 || isImporting}
                className="gap-1.5"
              >
                {isImporting ? (
                  <>
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    Importing…
                  </>
                ) : (
                  <>
                    Import {selected.size > 0 ? selected.size : ""} candidate{selected.size !== 1 ? "s" : ""}
                  </>
                )}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default RediscoveryDialog;

